			expected:      "/home/user/.claude/projects/myproject/agent-agent_abc123.jsonl",
		},
		{
			name:          "empty agent ID",
			transcriptDir: "/path/to/transcripts",
			agentID:       "",
			expected:      "/path/to/transcripts/agent-.jsonl",
		},
	}

	for _, tt := range tests {
